import{chromium}from'playwright-core';const b=await chromium.connectOverCDP('http://127.0.0.1:9224');try{const p=b.contexts().flatMap(x=>x.pages()).find(x=>x.url()==='http://127.0.0.1:30000/game');const z=await p.evaluate(()=>{if(!game.user.isGM||game.users.activeGM.id!==game.user.id)throw Error('no GM');return ['CAVHU07Scene0001','CAVSG01Scene0001'].map(id=>{const s=game.scenes.get(id);return {id,name:s.name,width:s.width,height:s.height,art:s.background.src,regions:Array.from(s.regions).map(r=>({id:r.id,name:r.name,shapes:r.toObject().shapes}))}})});console.log(JSON.stringify(z))}finally{await b.close()}